'use strict';

/**
* LAPACK routine to return the value of the one-norm, Frobenius norm, infinity-norm, or the largest absolute value of any element of a real symmetric matrix.
*
* @module @stdlib/lapack/base/dlansy
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dlansy = require( '@stdlib/lapack/base/dlansy' );
*
* var A = new Float64Array( [ 1.0, 2.0, 2.0, 5.0 ] );
*
* var norm = dlansy( 'row-major', 'M', 'upper', 2, A, 2 );
* // returns 5.0
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dlansy = require( '@stdlib/lapack/base/dlansy' );
*
* var A = new Float64Array( [ 1.0, 2.0, 2.0, 5.0 ] );
*
* var norm = dlansy.ndarray( 'M', 'upper', 2, A, 2, 1, 0 );
* // returns 5.0
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var dlansy;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dlansy = main;
} else {
	dlansy = tmp;
}


// EXPORTS //

module.exports = dlansy;

// exports: { "ndarray": "dlansy.ndarray" }
